import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import PaymentRequestsPage from "@/app/(app)/finance/payment-requests/page";

const dependencies = vi.hoisted(() => ({
  getCachedDatabasePermissions: vi.fn(),
  getPaymentRequestsResult: vi.fn(),
}));

vi.mock("@/lib/permissions/database-permissions", () => ({
  getCachedDatabasePermissions: dependencies.getCachedDatabasePermissions,
}));
vi.mock("@/features/finance/data", () => ({
  getPaymentRequestsResult: dependencies.getPaymentRequestsResult,
}));
vi.mock("@/features/finance/payment-request-directory", () => ({
  PaymentRequestDirectory: ({
    canCancelPaymentRequests,
    canCreatePaymentRequests,
    canViewStudents,
    items,
    now,
    today,
  }: {
    canCancelPaymentRequests?: boolean;
    canCreatePaymentRequests: boolean;
    canViewStudents?: boolean;
    items: unknown[];
    now?: string;
    today?: string;
  }) => (
    <div>
      {`create:${String(canCreatePaymentRequests)} · cancel:${String(canCancelPaymentRequests)} · students:${String(canViewStudents)} · today:${today} · now:${now} · items:${items.length}`}
    </div>
  ),
}));

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
  vi.useRealTimers();
});

describe("Payment requests route authority (step 14c)", () => {
  it.each([
    [["payments.view"], "create:false · cancel:false · students:false"],
    // The create page refuses without students.view, so the button follows it.
    [["payments.view", "payments.create_request"], "create:false · cancel:false · students:false"],
    [["payments.view", "payments.create_request", "students.view"], "create:true · cancel:false · students:true"],
    // The accountant: payments.manage without students.view cancels but neither creates nor links profiles.
    [["payments.manage"], "create:false · cancel:true · students:false"],
    [["payments.manage", "students.view"], "create:true · cancel:true · students:true"],
  ])("derives the list's flags from %j and passes the Vietnam business date", async (codes, flags) => {
    // 18:30 UTC on 16/10 is already 17/10 in Vietnam.
    vi.useFakeTimers({ now: new Date("2026-10-16T18:30:00.000Z"), toFake: ["Date"] });
    dependencies.getCachedDatabasePermissions.mockResolvedValueOnce({ ok: true, permissions: codes });
    dependencies.getPaymentRequestsResult.mockResolvedValueOnce({ data: [{ id: "request-1" }], ok: true });

    render(await PaymentRequestsPage());

    // `now` is the render's own instant (the 14-day caption uses it, so SSR and hydration agree).
    expect(screen.getByText(`${flags} · today:2026-10-17 · now:2026-10-16T18:30:00.000Z · items:1`)).toBeInTheDocument();
    // The read itself is unchanged: no argument, one call.
    expect(dependencies.getPaymentRequestsResult).toHaveBeenCalledTimes(1);
    expect(dependencies.getPaymentRequestsResult).toHaveBeenCalledWith();
  });

  it("refuses without payments.view or payments.manage before loading anything", async () => {
    dependencies.getCachedDatabasePermissions.mockResolvedValueOnce({
      ok: true,
      permissions: ["finance.view", "payments.create_request", "students.view"],
    });

    render(await PaymentRequestsPage());

    expect(screen.getByText("Không có quyền xem yêu cầu thanh toán")).toBeInTheDocument();
    expect(screen.queryByText(/^create:/)).not.toBeInTheDocument();
    expect(dependencies.getPaymentRequestsResult).not.toHaveBeenCalled();
  });
});
